def distance_loop(a: list[float], b: list[float]) -> float:
    if len(a) != len(b):
        raise ValueError("The two points must have the same number of components.")

    total = 0.0
    for x, y in zip(a, b):
        total += (x - y) ** 2
    return math.sqrt(total)

def angle_between(a: np.ndarray, b: np.ndarray) -> float:
    a_len = np.linalg.norm(a)
    b_len = np.linalg.norm(b)
    if a_len == 0 or b_len == 0:
        raise ValueError("A zero vector has no direction, so there is no angle.")

    cos_theta = np.clip(np.dot(a, b) / (a_len * b_len), -1.0, 1.0)
    return float(np.degrees(np.arccos(cos_theta)))

def project(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    b_squared = np.dot(b, b)
    if b_squared == 0:
        raise ValueError("There is no line through the zero vector to project onto.")

    return (np.dot(a, b) / b_squared) * b

def nearest(query: np.ndarray, library: dict[str, np.ndarray]) -> str:
    if not library:
        raise ValueError("An empty library has no nearest item.")

    scores = {name: distance(query, vector) for name, vector in library.items()}
    return min(scores, key=scores.get)
